// n8n Code node - run once for all items
const results = [];

for (const item of $input.all()) {
  const stdout = item.json.stdout || '';

  // Find where the HTML actually starts
const match = stdout.match(/<!DOCTYPE html>|<html/i);
const html = match ? stdout.slice(match.index) : stdout;

  results.push({
    json: {
      html: html.trim(),
    },
  });
}

return results;

// Build a raw RFC 2822 message for the Gmail API.
//
// Gmail (web and mobile) does not render <img src="data:..."> images, so the
// banner that morning_report embeds as a data URI is lifted out of the HTML
// and attached as an inline multipart/related part referenced by Content-ID.
// The HTML part stays small, which also keeps Gmail from clipping the message.
const to = "you@example.com";
const subject = `Zachary's Digest - ${$now.toFormat('MMMM d, yyyy')}`;

const wrap76 = (s) => s.replace(/(.{76})/g, '$1\r\n');
const results = [];

for (const item of $input.all()) {
  let html = item.json.html || '';
  let png = null;
  const m = html.match(/src="data:image\/png;base64,([A-Za-z0-9+/=]+)"/);
  if (m) {
    png = m[1];
    html = html.replace(m[0], 'src="cid:banner"');
  }

  const boundary = 'digest-' + Date.now().toString(36);
  const encSubject = '=?UTF-8?B?' + Buffer.from(subject, 'utf8').toString('base64') + '?=';
  const htmlPart = [
    'Content-Type: text/html; charset=UTF-8',
    'Content-Transfer-Encoding: base64',
    '',
    wrap76(Buffer.from(html, 'utf8').toString('base64')),
  ];

  const lines = [`To: ${to}`, `Subject: ${encSubject}`, 'MIME-Version: 1.0'];
  if (png) {
    lines.push(
      `Content-Type: multipart/related; boundary="${boundary}"`,
      '',
      `--${boundary}`,
      ...htmlPart,
      `--${boundary}`,
      'Content-Type: image/png; name="banner.png"',
      'Content-Transfer-Encoding: base64',
      'Content-ID: <banner>',
      'Content-Disposition: inline; filename="banner.png"',
      '',
      wrap76(png),
      `--${boundary}--`,
    );
  } else {
    lines.push(...htmlPart);
  }

  results.push({
    json: {
      raw: Buffer.from(lines.join('\r\n'), 'utf8').toString('base64url'),
      hasBanner: Boolean(png),
    },
  });
}

return results;
